# find closures where close time is within window, but supports may be in [start-800,end]
from collections import defaultdict
closures = []
node_list = sorted(nodes)
for i in range(len(node_list)):
    for j in range(i+1,len(node_list)):
        a = node_list[i]; b = node_list[j]
        # supports: interactions of a or b with some c in win_all
        a_events = [e for e in win_all if e[0]==a or e[1]==a]
        b_events = [e for e in win_all if e[0]==b or e[1]==b]
        a_by_c = defaultdict(list)
        for u,v,t in a_events:
            c = v if u==a else u
            a_by_c[c].append(t)
        b_by_c = defaultdict(list)
        for u,v,t in b_events:
            c = v if u==b else u
            b_by_c[c].append(t)
        common_cs = set(a_by_c.keys()) & set(b_by_c.keys())
        for c in common_cs:
            for t1 in a_by_c[c]:
                for t2 in b_by_c[c]:
                    later = max(t1,t2)
                    closes = [e for e in win_all if ((e[0]==a and e[1]==b) or (e[0]==b and e[1]==a)) and e[2]>later and e[2]<=later+800 and e[2]>=start and e[2]<=end]
                    for e in closes:
                        closures.append({'a':a,'b':b,'c':c,'t1':t1,'t2':t2,'later':later,'close':e[2],'close_event':e})
print(len(closures))
